{"content": "import socket, sys, threading
import chall

class Client:
    def __init__(self, conn):
        self.conn = conn
        self.buf = b""
        self.f = conn.makefile('rwb', buffering=0)
    def send(self, data):
        self.f.write(data if isinstance(data, bytes) else data.encode())
    def readline(self):
        return self.f.readline()
    def close(self):
        try: self.f.close()
        except Exception: pass
        try: self.conn.close()
        except Exception: pass

def handle(conn):
    c = Client(conn)
    challenge = chall.Challenge(6, 16, 5, 50000)
    c.send("sbox: " + "".join(hex(i)[2:].zfill(2) for i in challenge.spn.SBOX) + "\n")
    PROMPT = ("Choose API option\n"
              "1. Test encryption\n"
              "2. Get Flag\n")
    while True:
        c.send(PROMPT)
        line = c.readline()
        if not line:
            break
        try:
            option = int(line.strip())
        except Exception:
            break
        if option == 1:
            c.send("(hex) text: ")
            line = c.readline()
            if not line:
                break
            text_hex = line.strip().decode()
            if len(text_hex) & 1:
                text_hex += "0"
            try:
                text = bytes.fromhex(text_hex)
            except Exception:
                c.send("bad hex\n")
                continue
            block_len = challenge.spn.BLOCK_SIZE // 8
            text += bytes((block_len - len(text)) % block_len)
            if challenge.quota < len(text)//block_len:
                c.send("Encryption quota exceeded\n")
                break
            challenge.quota -= len(text)//block_len
            c.send("Quota remaining: %d\n" % challenge.quota)
            ct = challenge.spn.encrypt_bytes(text)
            c.send(ct.hex() + "\n")
        elif option == 2:
            c.send("(int) key: ")
            line = c.readline()
            if not line:
                break
            try:
                key = int(line.strip())
            except Exception:
                c.send("bad key\n")
                break
            if key == challenge.spn.round_keys[0]:
                try:
                    from flag import flag
                    c.send(str(flag) + "\n")
                except Exception:
                    c.send("FAKEFLAG{test_local}\n")
            else:
                c.send("There is no free lunch\n")
            break
        else:
            break
    c.close()

def main():
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 31337
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    s.bind(("127.0.0.1", port))
    s.listen(5)
    print("listening", port, flush=True)
    while True:
        conn, _ = s.accept()
        threading.Thread(target=handle, args=(conn,), daemon=True).start()

if __name__ == "__main__":
    main()
