{"content": "import socket, re, random, sys, time

BS, NB, N = 6, 16, 96
MASK = (1 << N) - 1
PB = [(BS * i + j) % (NB * BS) for j in range(BS) for i in range(NB)]


class Cipher:
    def __init__(self, sbox):
        self.SBOX = sbox
        self.SINV = [sbox.index(i) for i in range(64)]
        self.PBOX = PB
        self.round_keys = None

    def perm(self, inp):
        ct = 0
        for i, v in enumerate(self.PBOX):
            ct |= (inp >> (N - 1 - i) & 1) << (N - 1 - v)
        return ct

    def sbox(self, inp):
        ct = 0
        for i in range(NB):
            ct |= self.SBOX[(inp >> (BS * i)) & 63] << (BS * i)
        return ct

    def expand_key(self, key, rounds=5):
        keys = [key]
        for _ in range(rounds):
            val = keys[-1]
            keys.append(self.sbox((val << 7 | val >> (N - 7)) & MASK))
        return keys

    def encrypt(self, pt):
        ct = pt ^ self.round_keys[0]
        for rk in self.round_keys[1:-1]:
            ct = self.perm(self.sbox(ct)) ^ rk
        ct = self.sbox(ct)
        return ct ^ self.round_keys[-1]

    def set_key(self, key):
        self.round_keys = self.expand_key(key)

    def inv_schedule(self, rk5, steps=5):
        cur = rk5
        for _ in range(steps):
            v = 0
            for i in range(NB):
                v |= self.SINV[(cur >> (BS * i)) & 63] << (BS * i)
            cur = (v >> 7 | v << (N - 7)) & MASK
        return cur


class Conn:
    def __init__(self, host, port, timeout=120):
        self.s = socket.create_connection((host, port), timeout=timeout)
        self.s.settimeout(timeout)
        self.buf = b""

    def recv_until(self, marker):
        while marker not in self.buf:
            chunk = self.s.recv(1 << 16)
            if not chunk:
                break
            self.buf += chunk
        idx = self.buf.find(marker)
        if idx < 0:
            out, self.buf = self.buf, b""
            return out
        end = idx + len(marker)
        out, self.buf = self.buf[:end], self.buf[end:]
        return out

    def recv_all(self):
        while True:
            try:
                chunk = self.s.recv(1 << 16)
            except socket.timeout:
                break
            if not chunk:
                break
            self.buf += chunk
        out, self.buf = self.buf, b""
        return out

    def sendline(self, data):
        if isinstance(data, str):
            data = data.encode()
        self.s.sendall(data + b"\n")

    def close(self):
        try:
            self.s.close()
        except Exception:
            pass


def recover(cipher, counts, structs, plaintexts, ciphertexts, topk=1):
    """counts: [16][64]; structs: list of list of chunk values per structure."""
    rk5 = 0
    for j in range(16):
        best = max(range(64), key=lambda k: counts[j][k])
        rk5 |= best << (BS * j)
    key = cipher.inv_schedule(rk5)
    cipher.set_key(key)
    ok = True
    for pt, ct in zip(plaintexts, ciphertexts):
        if cipher.encrypt(pt) != ct:
            ok = False
            break
    return key, ok


def attack(host, port, target_structs=20, batch_size=8, max_structs=600, verbose=True):
    conn = Conn(host, port)
    banner = conn.recv_until(b"2. Get Flag")
    if verbose:
        print("[*] banner:", banner[:200])
    m = re.search(rb"sbox:\s*([0-9a-fA-F]{128})", banner)
    if not m:
        raise RuntimeError("could not parse sbox from banner: %r" % banner[:500])
    sbox = [int(m.group(1)[i:i + 2], 16) for i in range(0, 128, 2)]
    cipher = Cipher(sbox)
    rng = random.Random(int(time.time()) ^ 0x5f3759df)

    counts = [[0] * 64 for _ in range(16)]
    struct_chunks = []          # per structure: list of 16 lists of 64 chunk values
    all_pts = []
    all_cts = []
    nstruct = 0

    while nstruct < max_structs:
        # build a batch of structures
        batch = []
        for _ in range(min(batch_size, target_structs - nstruct) if nstruct < target_structs else batch_size):
            g = rng.randrange(16)
            const = rng.getrandbits(N) & ~(63 << (BS * g)) & MASK
            texts = [const | (v << (BS * g)) for v in range(64)]
            batch.append(texts)
        if not batch:
            break
        payload = b"".join(t.to_bytes(N // 8, 'big') for texts in batch for t in texts)
        conn.sendline(b"1")
        conn.recv_until(b"(hex) text: ")
        conn.sendline(payload.hex())
        resp = conn.recv_until(b"2. Get Flag")
        m2 = re.search(rb"Quota remaining: (-?\d+)\n([0-9a-f]+)", resp)
        if not m2:
            raise RuntimeError("bad response: %r" % resp[:500])
        quota = int(m2.group(1))
        hexstr = m2.group(2).decode()
        if len(hexstr) != len(payload) * 2:
            raise RuntimeError("ciphertext length mismatch: %d vs %d" % (len(hexstr), len(payload) * 2))
        blocks = [int(hexstr[i:i + 24], 16) for i in range(0, len(hexstr), 24)]
        # accumulate counts
        pos = 0
        for texts in batch:
            cts = blocks[pos:pos + 64]; pos += 64
            chunkvals = []
            for j in range(16):
                vals = [(c >> (BS * j)) & 63 for c in cts]
                chunkvals.append(vals)
                row = counts[j]
                for k in range(64):
                    x = 0
                    for cv in vals:
                        x ^= cipher.SINV[cv ^ k]
                    if x == 0:
                        row[k] += 1
            struct_chunks.append(chunkvals)
            all_pts.extend(texts)
            all_cts.extend(cts)
        nstruct += len(batch)
        if verbose:
            print(f"[*] structures={nstruct} quota_remaining={quota}")
        if nstruct >= target_structs:
            key, ok = recover(cipher, counts, struct_chunks, all_pts, all_cts)
            if verbose:
                margins = []
                for j in range(16):
                    src = sorted(range(64), key=lambda k: -counts[j][k])
                    margins.append((src[0], counts[j][src[0]], counts[j][src[1]]))
                print("[*] candidate margins:", margins)
            if ok:
                print("[+] recovered key:", key)
                conn.sendline(b"2")
                conn.recv_until(b"(int) key: ")
                conn.sendline(str(key))
                out = conn.recv_all()
                print("[+] server response:", out)
                conn.close()
                return key, out
            else:
                print("[-] verification failed, gathering more structures")
                target_structs += 8
        if quota < 128:
            break
    conn.close()
    return None, None


if __name__ == "__main__":
    host = sys.argv[1] if len(sys.argv) > 1 else "challenge"
    port = int(sys.argv[2]) if len(sys.argv) > 2 else 1337
    attack(host, port)
